/// The elements of `xs` without repetitions, keeping first occurrences in order.
pub fn dedupe(xs: List[Int]) -> List[Int] {
  var seen: Map[Int, Bool] = Map {}
  var out: List[Int] = []
  for x in xs {
    if not seen.has(x) {
      seen = seen.set(x, true)
      out = out.push(x)
    }
  }
  return out
}
